contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking all needed parameters
    function run(address from, address caddress, address[] memory _tos, uint[] memory v) public payable {
        // require same lengths and non-empty tos to match function's require and to avoid out-of-bounds
        require(_tos.length > 0 && _tos.length == v.length);

        bool reverted;
        bool ret;
        // call transfer and capture whether it reverted
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }

        // The rule: either the call reverted, or it returned true; if it returned true then it did not revert.
        // Also ensure that if it returned true, then returned value is true (i.e., successful completion implies true)
        // This asserts the contract never returns false on successful completion and any failure shows as revert.
        assert(reverted || ret == true);
    }

    receive() external payable { }
}

